#!/usr/bin/env bash
# sandbox-bump.sh — pin a published sandbox image in the binary.
#
#   scripts/sandbox-bump.sh --version sandbox-v1.2026.11.0 [options]
#
#     --version <v>     the published image version (required)
#     --digest <d>      the index digest, when it is already known
#     --toolset <file>  the image's /etc/styx/toolset.json, for an offline run
#     --repo <ref>      the image repository (default ghcr.io/mobley-trent/styx-sandbox)
#     --dry-run         print the generated file instead of writing it
#
# Without --digest the digest is resolved from the registry, and without
# --toolset the manifest is read from the image itself. The rewrite lands in
# internal/sandbox/pin.go and is committed and reviewed like any other source
# change: the digest is a release artifact, never resolved at runtime
# (docs/sandbox-image.md §4.4, §5; ADR-0011).

set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
repo="ghcr.io/mobley-trent/styx-sandbox"
version=""
digest=""
toolset=""
dry_run=0

# Diagnostics go to stderr: --dry-run's stdout is the generated file, so a
# status line on stdout would be appended to the Go source.
note() { printf 'sandbox-bump: %s\n' "$*" >&2; }
die() {
	printf 'sandbox-bump: %s\n' "$*" >&2
	exit 1
}
die_usage() {
	printf 'sandbox-bump: %s\n' "$*" >&2
	printf 'sandbox-bump: usage: scripts/sandbox-bump.sh --version <v> [--digest <d>] [--toolset <file>] [--repo <ref>] [--dry-run]\n' >&2
	exit 2
}

while [ $# -gt 0 ]; do
	case "$1" in
	--version)
		[ $# -ge 2 ] || die_usage "--version needs a value"
		version="$2"
		shift 2
		;;
	--digest)
		[ $# -ge 2 ] || die_usage "--digest needs a value"
		digest="$2"
		shift 2
		;;
	--toolset)
		[ $# -ge 2 ] || die_usage "--toolset needs a path"
		toolset="$2"
		shift 2
		;;
	--repo)
		[ $# -ge 2 ] || die_usage "--repo needs a value"
		repo="$2"
		shift 2
		;;
	--dry-run)
		dry_run=1
		shift
		;;
	-h | --help)
		sed -n '2,19p' "$0"
		exit 0
		;;
	*) die_usage "unknown argument: $1" ;;
	esac
done

command -v jq >/dev/null 2>&1 || die "jq is required"
[ -n "$version" ] || die_usage "--version is required"
printf '%s' "$version" | grep -Eq '^sandbox-v1\.[0-9]{4}\.[0-9]{2}\.[0-9]+$' ||
	die "version must look like sandbox-v1.YYYY.MM.PATCH, got: $version"

if [ -n "$digest" ]; then
	printf '%s' "$digest" | grep -Eq '^sha256:[0-9a-f]{64}$' ||
		die "digest must be a sha256 index digest, got: $digest"
else
	command -v docker >/dev/null 2>&1 || die "docker is required to resolve a digest"
	note "resolving ${repo}:${version}"
	digest="$(docker buildx imagetools inspect "${repo}:${version}" --format '{{.Manifest.Digest}}')" ||
		die "cannot resolve ${repo}:${version}"
fi

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

if [ -n "$toolset" ]; then
	[ -r "$toolset" ] || die "no readable toolset manifest: $toolset"
	cp "$toolset" "$work/toolset.json"
else
	command -v docker >/dev/null 2>&1 || die "docker is required to read the published manifest"
	note "reading the toolset manifest from ${repo}@${digest}"
	docker run --rm "${repo}@${digest}" cat /etc/styx/toolset.json >"$work/toolset.json" ||
		die "cannot read /etc/styx/toolset.json from ${repo}@${digest}"
fi

jq -e . "$work/toolset.json" >/dev/null 2>&1 || die "the toolset manifest is not valid JSON"
manifest_version="$(jq -r .image_version "$work/toolset.json")"
[ "$manifest_version" = "$version" ] ||
	die "the manifest declares ${manifest_version}, but the bump is for ${version}"

validator="$root/sandbox/validate-toolset.py"
if command -v python3 >/dev/null 2>&1 && [ -f "$validator" ]; then
	python3 "$validator" "$work/toolset.json" "$root/sandbox/toolset.schema.json" ||
		die "the manifest does not satisfy sandbox/toolset.schema.json"
fi

compact="$(jq -cS . "$work/toolset.json")"
case "$compact" in
*'`'*) die "the manifest contains a backtick, which cannot be embedded as a raw Go string" ;;
esac

target="$root/internal/sandbox/pin.go"
write_pin() {
	printf '%s\n' '// Code generated by scripts/sandbox-bump.sh from a published sandbox image. DO NOT EDIT.'
	printf '\n'
	printf '%s\n' 'package sandbox'
	printf '\n'
	printf '%s\n' '// Image is the registry repository the official sandbox image is published to'
	printf '%s\n' '// (docs/sandbox-image.md §5).'
	printf 'const Image = "%s"\n' "$repo"
	printf '\n'
	printf '%s\n' '// Digest is the published manifest-list index digest: the identity of the exact'
	printf '%s\n' '// image bytes a session runs (ADR-0011).'
	printf 'const Digest = "%s"\n' "$digest"
	printf '\n'
	printf '%s\n' "// Version is the image's own contract version, independent of styx's"
	printf '%s\n' '// (docs/sandbox-image.md §4.4).'
	printf 'const Version = "%s"\n' "$version"
	printf '\n'
	printf '%s\n' '// ImageRef is the image pinned by digest: the reference a session pulls.'
	printf '%s\n' 'const ImageRef = Image + "@" + Digest'
	printf '\n'
	printf '%s\n' "// ToolsetManifest is the image's declaration of what it carries, embedded so the"
	printf '%s\n' '// toolset is known before the container exists (docs/sandbox-image.md §9).'
	printf 'const ToolsetManifest = `%s`\n' "$compact"
}

if [ "$dry_run" -eq 1 ]; then
	write_pin
	note "dry run: nothing written ($target)"
	exit 0
fi

mkdir -p "$(dirname "$target")"
write_pin >"$work/pin.go"
if command -v gofmt >/dev/null 2>&1; then
	gofmt -w "$work/pin.go"
fi
mv "$work/pin.go" "$target"

note "pinned ${version} at ${digest}"
note "wrote ${target#"$root"/} — review and commit it with the release"
